from pathlib import Path

path = Path('.github/pr41-native-text-v5.py')
text = path.read_text(encoding='utf-8')

old = '''old = \'\'\'        let raw = assess_text_quality(&page.text);\n        let extraction_failed = document.native_text_failed_pages.contains(&page_number);\n        if extraction_failed || raw.suspicious {\n            let mut reasons = if extraction_failed {\n                vec!["native_text_extraction_failed"]\n            } else {\n                raw.reasons.clone()\n            };\n            if extraction_failed && raw.suspicious {\n                reasons.extend(raw.reasons.iter().copied());\n            }\n            reasons.sort_unstable();\n            reasons.dedup();\n            ocr_pages.push(OcrPageCandidate {\n                page_number,\n                required: true,\n                reasons,\n            });\n            continue;\n        }\n        if page.text.trim().is_empty() && !has_good_semantics {\n\'\'\'\nnew = \'\'\'        let raw = assess_text_quality(&page.text);\n        let extraction_failed = document.native_text_failed_pages.contains(&page_number);\n        if extraction_failed {\n            let mut reasons = vec!["native_text_extraction_failed"];\n            reasons.extend(raw.reasons.iter().copied());\n            reasons.sort_unstable();\n            reasons.dedup();\n            ocr_pages.push(OcrPageCandidate {\n                page_number,\n                required: true,\n                reasons,\n            });\n            continue;\n        }\n        if page.text.trim().is_empty() && !has_good_semantics {\n\'\'\'\n'''
actual = '''old = \'\'\'        let raw = assess_text_quality(&page.text);\n        let extraction_failed = failed_pages.contains(&page.page_number);\n        let structured_is_suspicious = semantic_suspicious.contains(&page.page_number);\n        let has_good_semantic = semantic_good.contains(&page.page_number);\n\n        if extraction_failed || raw.suspicious {\n            let mut reasons = raw.reasons.clone();\n            if extraction_failed {\n                reasons.push("native_extraction_failed");\n            }\n            reasons.sort_unstable();\n            reasons.dedup();\n            ocr_pages.push(OcrPageCandidate {\n                page_number: page.page_number,\n                required: true,\n                reasons,\n            });\n            continue;\n        }\n\n        // Readable native text stays authoritative even when a page is short.\n        // A title, heading, caption, or other sparse page is not evidence that\n        // oxidize-pdf failed, and replacing it with OCR usually lowers fidelity.\n        // OCR is therefore reserved for genuinely empty native text (or the\n        // required corruption/failure cases above). PDFium renders remain\n        // available as visual grounding for providers with image capability.\n        if page.text.trim().is_empty() && !has_good_semantic {\n\'\'\'\nnew = \'\'\'        let raw = assess_text_quality(&page.text);\n        let extraction_failed = failed_pages.contains(&page.page_number);\n        let structured_is_suspicious = semantic_suspicious.contains(&page.page_number);\n        let has_good_semantic = semantic_good.contains(&page.page_number);\n\n        if extraction_failed {\n            let mut reasons = raw.reasons.clone();\n            reasons.push("native_extraction_failed");\n            reasons.sort_unstable();\n            reasons.dedup();\n            ocr_pages.push(OcrPageCandidate {\n                page_number: page.page_number,\n                required: true,\n                reasons,\n            });\n            continue;\n        }\n\n        // Empty native text may still benefit from OCR. Localized malformed\n        // glyphs in otherwise readable native text are handled below without\n        // replacing the page with raster OCR.\n        if page.text.trim().is_empty() && !has_good_semantic {\n\'\'\'\n'''
if text.count(old) != 1:
    raise SystemExit('old generated first recovery template not found')
text = text.replace(old, actual, 1)

old2 = '''old = \'\'\'        if !raw.substantive || has_suspicious_semantics || document.semantic_analysis_degraded {\n            native_semantic_fallback_pages.push(page_number);\n        }\n\'\'\'\nnew = \'\'\'        if native_page_requires_ocr(&page.text, &raw) {\n            ocr_pages.push(OcrPageCandidate {\n                page_number,\n                required: true,\n                reasons: raw.reasons.clone(),\n            });\n            continue;\n        }\n        if raw.suspicious\n            || !raw.substantive\n            || has_suspicious_semantics\n            || document.semantic_analysis_degraded\n        {\n            // A page can contain malformed glyph mappings while its surrounding\n            // native prose remains perfectly readable. In that case rebuild\n            // semantics from cleaned native page text; do not pay the OCR cost.\n            native_semantic_fallback_pages.push(page_number);\n        }\n\'\'\'\n'''
actual2 = '''old = \'\'\'        if !raw.substantive || structured_is_suspicious || document.semantic_analysis_degraded {\n            native_semantic_fallback_pages.insert(page.page_number);\n        }\n\'\'\'\nnew = \'\'\'        if native_page_requires_ocr(&page.text, &raw) {\n            ocr_pages.push(OcrPageCandidate {\n                page_number: page.page_number,\n                required: true,\n                reasons: raw.reasons.clone(),\n            });\n            continue;\n        }\n        if raw.suspicious\n            || !raw.substantive\n            || structured_is_suspicious\n            || document.semantic_analysis_degraded\n        {\n            // Localized font-map damage invalidates structured semantics, not\n            // the readable page. Rebuild from cleaned native text without OCR.\n            native_semantic_fallback_pages.insert(page.page_number);\n        }\n\'\'\'\n'''
if text.count(old2) != 1:
    raise SystemExit('old generated fallback template not found')
text = text.replace(old2, actual2, 1)

if text.count('TextRecoveryPlan') != 1:
    raise SystemExit(f'expected one generated TextRecoveryPlan marker, found {text.count("TextRecoveryPlan")}')
text = text.replace('TextRecoveryPlan', 'ExtractionRecoveryPlan', 1)

needle = 'let document = base_document(page, "\\\\u{e01c} bad semantic font mapping");'
replacement = 'let document = base_document(page, "\\\\u{e01c}\\\\u{e01d} bad semantic font mapping");'
if text.count(needle) != 1:
    raise SystemExit(f'expected one Nunn semantic regression marker, found {text.count(needle)}')
text = text.replace(needle, replacement, 1)

path.write_text(text, encoding='utf-8')
